 if(body.total_capital!==25000||body.confirmation!=='ARCHIVE_OLD_DEMO_AND_RESET_20261012')return json({error:'EXACT_RESET_CONFIRMATION_REQUIRED'},422);
 const prior=await env.DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='demo_20261012_reset_applied'").first();
 if(prior&&await env.DB.prepare("SELECT id FROM demo_20261012_reset_applied WHERE id='20261012_25000'").first())return json({ok:true,already_applied:true,paper_only:true});
 const backup=await env.DB.prepare("SELECT COUNT(*) n FROM demo_20261012_before_virtual_trades").first();
