function validEdgeSnapshot(b,now){return b?.version===1&&(b.mode==='DELAYED_DEMO_15M'||(b.mode==='IDEAL_LIVE_PAPER'&&b.source_provider==='IDEAL_UDP'&&b.expected_delay_seconds===0))&&b.paper_only===true&&b.orders_sent===0&&b.ledger_scope==='LOCAL_FORK_FROM_VERIFIED_BACKUP'&&Number.isFinite(Date.parse(b.wall_time))&&Math.abs(now-Date.parse(b.wall_time))<=120000&&Math.abs(Date.parse(b.wall_time)-Date.parse(b.evaluation_time)-(b.mode==='IDEAL_LIVE_PAPER'?0:900000))<=1000&&Array.isArray(b.accounts)&&b.accounts.length===2&&Array.isArray(b.trades)&&b.trades.length<=100&&Array.isArray(b.candidates)&&b.candidates.length<=100;}
async function edgeSnapshot(request,env,now=Date.now()){
 if(!env.PANEL_ARCHIVE)return json({error:'PANEL_BRIDGE_NOT_CONFIGURED'},503);
 const b=await readBody(request);if(!validEdgeSnapshot(b,now))return json({error:'INVALID_EDGE_SNAPSHOT'},422);
 const last=await env.PANEL_ARCHIVE.get('edge:latest','json');
 if(last&&Date.parse(last.wall_time)>=Date.parse(b.wall_time))return json({ok:true,duplicate:true});
 if(last&&Date.parse(b.wall_time)-Date.parse(last.wall_time)<55000)return json({error:'SNAPSHOT_INTERVAL_60_SECONDS'},429);
 await env.PANEL_ARCHIVE.put('edge:latest',JSON.stringify({...b,cloud_received_at:new Date(now).toISOString()}),{expirationTtl:7*86400});
 return json({ok:true,wall_time:b.wall_time,paper_only:true});
}
