 return {...withSectorData(b),connected:!stale,transport:'LIVE_PUSH',transport_stale:stale,feed_state:stale?'PC_DISCONNECTED':b.feed_state,snapshot_age_seconds:Math.max(0,Math.round(age/1000))};
