export class EdgeLiveHub extends DurableObject {
 constructor(ctx,env) {
  super(ctx,env);
  this.ctx.storage.sql.exec('CREATE TABLE IF NOT EXISTS latest(id INTEGER PRIMARY KEY CHECK(id=1),payload TEXT NOT NULL,seq INTEGER NOT NULL)');
 }
 current() {
  const rows=this.ctx.storage.sql.exec('SELECT payload,seq FROM latest WHERE id=1').toArray();
  return rows.length?{...JSON.parse(rows[0].payload),live_sequence:rows[0].seq}:null;
 }
 publish(b,now=Date.now()) {
  if(!validEdgeSnapshot(b,now))return {error:'INVALID_EDGE_SNAPSHOT'};
  const prior=this.current();
  if(prior&&Date.parse(b.wall_time)<=Date.parse(prior.wall_time))return {ok:true,duplicate:true,sequence:prior.live_sequence};
  if(prior&&Date.parse(b.wall_time)-Date.parse(prior.wall_time)<500)return {error:'LIVE_RATE_LIMIT'};
  const seq=(prior?.live_sequence||0)+1,data={...b,cloud_received_at:new Date(now).toISOString()};
  this.ctx.storage.sql.exec('INSERT INTO latest VALUES(1,?,?) ON CONFLICT(id) DO UPDATE SET payload=excluded.payload,seq=excluded.seq',JSON.stringify(data),seq);
  const payload=JSON.stringify({type:'snapshot',data:liveEdgeView({...data,live_sequence:seq},now)});
  for(const ws of this.ctx.getWebSockets()) {
   try{if(ws.deserializeAttachment()?.expires<=now){ws.close(1008,'Session expired');continue;}ws.send(payload);}catch{try{ws.close(1011,'Reconnect');}catch{}}
  }
  return {ok:true,sequence:seq,paper_only:true};
 }
 read(now=Date.now()) {return liveEdgeView(this.current(),now);}
 async fetch(request) {
  if(request.headers.get('Upgrade')?.toLowerCase()!=='websocket')return json({error:'WEBSOCKET_REQUIRED'},426);
  const expires=Number(request.headers.get('x-edge-auth-until'));
  if(!Number.isFinite(expires)||expires<=Date.now()||expires>Date.now()+15*86400000)return json({error:'Unauthorized'},401);
  if(this.ctx.getWebSockets().length>=20)return json({error:'LIVE_VIEWER_LIMIT'},429);
  const [client,server]=Object.values(new WebSocketPair());
  server.serializeAttachment({expires});this.ctx.acceptWebSocket(server);
  server.send(JSON.stringify({type:'snapshot',data:this.read()}));
  return new Response(null,{status:101,webSocket:client});
 }
 webSocketMessage(ws,message) {
  const now=Date.now();if(ws.deserializeAttachment()?.expires<=now){ws.close(1008,'Session expired');return;}
  if(typeof message!=='string'||message.length>128||message!=='ping'){ws.close(1008,'Read only channel');return;}
  ws.send(JSON.stringify({type:'heartbeat',at:now,sequence:this.current()?.live_sequence||0}));
 }
 webSocketClose(ws,code,reason){ws.close(code,reason);}
 webSocketError(ws){try{ws.close(1011,'Reconnect');}catch{}}
}

