 const all=(opportunityData.opportunities||[]).filter(x=>x.strategy===opportunityEngine),items=all.filter(x=>matchesSector(x)&&(opportunityStage==='ALL'||x.stages.some(s=>s.stage===opportunityStage))),container=document.getElementById('opportunityList');container.replaceChildren();
